        background: var(--text);
        color: #020617;
        font-weight: 700;
        padding: 0.75rem 1rem;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--focus);
      }

