        padding: 2rem 1rem;
      }

      header {
        padding: 2rem 0 1rem;
      }

      main {
        display: grid;
        grid-template-columns: minmax(0, 0.9fr) minmax(20rem, 1.1fr);
        gap: 2rem;
        align-items: center;
        min-height: calc(100vh - 8rem);
