        font-size: 0.875rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        margin: 0 0 0.75rem;
        text-transform: uppercase;
      }

      h1 {
        font-size: clamp(2.25rem, 8vw, 4.8rem);
        line-height: 0.95;
        margin: 0 0 1rem;
        overflow-wrap: anywhere;
      }

