        width: 100%;
        min-width: 0;
        border: 1px solid var(--panel-border);
        border-radius: 1.5rem;
        background: linear-gradient(180deg, #111827, #0f172a);
        box-shadow: 0 1.5rem 5rem #000000;
        padding: clamp(1.25rem, 4vw, 2rem);
