      input:hover {
        border-color: var(--muted);
      }

      input:focus {
        border-color: var(--focus);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #1e40af;
      }

      input[aria-invalid="true"] {
        border-color: var(--error);
