        display: block;
        font-size: 0.925rem;
        margin-top: 0.45rem;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-message {
        color: var(--error);
        font-weight: 700;
      }

      button {
        width: 100%;
        border: 1px solid #7dd3fc;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        color: #04111f;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        padding: 0.95rem 1.25rem;
      }

      button:hover {
        background: linear-gradient(135deg, #7dd3fc, var(--accent));
      }

      button:focus {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px var(--focus);
      }

      .form-status {
        min-height: 1.5rem;
        color: var(--success);
        font-weight: 700;
        margin: 1rem 0 0;
      }

      @media (max-width: 48rem) {
        main {
          grid-template-columns: 1fr;
          align-items: start;
          min-height: auto;
        }
      }

      @media (forced-colors: active) {
        body,
        .card,
        input,
        button,
        .skip-link {
          background: Canvas;
          color: CanvasText;
        }

        .card,
        input,
        button {
          border-color: ButtonBorder;
        }

        input:focus,
        button:focus,
        .skip-link:focus {
          outline: 3px solid ButtonText;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div class="page-shell">
      <header>
        <p class="eyebrow">Support</p>
      </header>
      <main id="main-content">
        <section class="intro" aria-labelledby="page-title">
          <h1 id="page-title">How can we help?</h1>
          <p>Send our support team your contact details and we will get the right specialist in touch.</p>
        </section>

        <section class="card" aria-labelledby="form-title">
          <h2 id="form-title">Contact support</h2>
          <form id="support-form" action="#" method="post">
            <div class="form-field">
              <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
              <input id="full-name" name="fullName" type="text" autocomplete="name" required aria-required="true" placeholder="Alex Morgan">
            </div>

            <div class="form-field">
              <label for="email">Email address <span class="required-marker" aria-hidden="true">*</span></label>
              <input id="email" name="email" type="email" autocomplete="email" required aria-required="true" placeholder="alex@example.com">
            </div>

            <div class="form-field">
              <label for="phone">Phone number <span class="helper-text">(optional)</span></label>
              <input id="phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-help" placeholder="+1 555 123 4567">
              <span class="helper-text" id="phone-help">Use international format when possible, such as +1 555 123 4567.</span>
            </div>

            <button type="submit">Submit request</button>
            <p class="form-status" id="form-status" aria-live="polite"></p>
          </form>
        </section>
      </main>
    </div>

    <script>
      const Field = ({ id, label, required = false, optional = false, helperId, helperText, ...inputProps }) => ({
        id,
        label,
        required,
        optional,
        helperId,
        helperText,
        inputProps
      });

      const SupportContactForm = () => ({
        fields: [
          Field({ id: "full-name", label: "Full name", required: true, name: "fullName", type: "text" }),
          Field({ id: "email", label: "Email address", required: true, name: "email", type: "email" }),
          Field({
            id: "phone",
            label: "Phone number",
            optional: true,
            helperId: "phone-help",
            helperText: "Use international format when possible, such as +1 555 123 4567.",
            name: "phone",
            type: "tel"
          })
        ]
      });

      const form = document.querySelector("#support-form");
      const status = document.querySelector("#form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";

        if (!form.checkValidity()) {
          form.reportValidity();
          return;
        }

        status.textContent = "Thanks. Your support request is ready to send.";
        form.reset();
      });

      SupportContactForm();
    </script>
  </body>
</html>
